// -----------------------------------------------------------------------
// Les dictionnaires weapon_type / objective_type et les locales de date
// vivent maintenant dans utils/typeLabels.js (partagé avec popupUtils.js,
// qui n'a pas accès à React). Voir translateWeaponType / translateObjectiveType
// plus bas, qui délèguent à ce module partagé avec la langue active.
// -----------------------------------------------------------------------

// Langue des étiquettes de la carte MapTiler pour chaque langue de l'app.
// Valeurs = codes ISO 639-1 acceptés par maptilersdk (voir maptilersdk.Language).
// Pour ajouter une langue : ajouter la même clé que dans `translations`.
const MAP_LANGUAGES = {
  fr: "fr",
  en: "en",
  es: "es",
};

// Ordre de rotation de toggleLang (une entrée par langue de `translations`).
const LANG_ORDER = ["fr", "en", "es"];

const LangContext = createContext(null);

export function LangProvider({ children, defaultLang }) {
  const [lang, setLang] = useState(() => {
    // 1. Choix déjà mémorisé
    const saved = localStorage.getItem("lang");
    if (saved && translations[saved]) return saved;
    // 2. Langue par défaut imposée par le parent (optionnel)
    if (defaultLang && translations[defaultLang]) return defaultLang;
    // 3. Langue du navigateur
    const browserLang = navigator.language?.slice(0, 2);
    return translations[browserLang] ? browserLang : "en";
  });

  useEffect(() => {
    localStorage.setItem("lang", lang);
    // SEO / accessibilité : langue du document et titre de l'onglet
    document.documentElement.lang = lang;
    // Sur /content/<slug>/, c'est TheaterPage qui gère le titre (les effets du
    // parent s'exécutent APRÈS ceux de l'enfant : on écraserait son titre).
    if (!isTheaterPagePath()) {
      document.title = translations[lang].pageTitle;
      // <meta name="description"> suit aussi la langue (la balise existe dans index.html)
      document
        .querySelector('meta[name="description"]')
        ?.setAttribute("content", translations[lang].metaDescription);
    }
  }, [lang]);

  // Dictionnaire { entity_name: entity_name_fr } issu de world_areas (bootstrap).
  // Alimenté une fois par MapView via setEntityNamesFr.
  const [entityNamesFr, setEntityNamesFr] = useState({});

  // Dictionnaire { name: name_fr } issu de NON_STATE_ACTORS (bootstrap).
  // Alimenté une fois par MapView via setActorNamesFr.
  const [actorNamesFr, setActorNamesFr] = useState({});

  // Passe à la langue suivante (fr -> en -> es -> fr). Pour un sélecteur
  // explicite, utiliser plutôt setLang("fr" | "en" | "es").
  const toggleLang = () =>
    setLang((l) => LANG_ORDER[(LANG_ORDER.indexOf(l) + 1) % LANG_ORDER.length]);

  // Traduit une valeur brute de weapon_type / objective_type vers le libellé
  // dans la langue active, en délégant au module partagé (aussi utilisé par
  // popupUtils.js qui n'a pas accès à React).
  const translateWeaponType = (rawValue) => translateWeaponTypeShared(rawValue, lang);
  const translateObjectiveType = (rawValue) => translateObjectiveTypeShared(rawValue, lang);

  // Traduit un nom d'entité (pays, zone...) : en français via world_areas.entity_name_fr,
  // sinon (ou si inconnu) renvoie la valeur brute. Pas encore de colonne ES :
  // en espagnol, le nom anglais est affiché tel quel.
  const translateEntity = (name) =>
    lang === "fr" ? (entityNamesFr[name] ?? name) : name;

  // Traduit un nom d'acteur non étatique : name_fr en français,
  // sinon (ou si inconnu) renvoie la valeur brute (name).
  const translateActor = (name) =>
    lang === "fr" ? (actorNamesFr[name] ?? name) : name;

  const value = {
    lang,
    setLang,
    toggleLang,
    t: translations[lang],
    mapLanguage: MAP_LANGUAGES[lang] ?? "en",
    dateLocale: DATE_LOCALES[lang] ?? DATE_LOCALES.en,
    availableLangs: LANG_ORDER,
    translateWeaponType,
    translateObjectiveType,
    setEntityNamesFr,
    translateEntity,
    setActorNamesFr,
    translateActor,
  };

  return <LangContext.Provider value={value}>{children}</LangContext.Provider>;
}

export const useLang = () => {
  const ctx = useContext(LangContext);
  if (!ctx) {
    throw new Error("useLang doit être utilisé à l'intérieur d'un <LangProvider>");
  }
  return ctx;
};